// Non-promoting feasibility bridge from the exact complete-SEA3 continuum
// fixed-history member to the deployed measurement-only startup frontend.
//
// Input is one scalar per line: the up-positive non-gravitational vertical CoG
// acceleration generated by ou3_sea3_fixed_history_prehistory.py.  Those values
// are not a replay or a finite harmonic approximation; the Python producer
// derives them from the same continuum Hilbert-ball driver as the 601-sample
// feasibility word.  This executable only asks whether the unchanged shipping
// C++ frontend reaches its real TunerReady state on that exact prehistory.
#define EIGEN_NON_ARDUINO

#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <string>
#include <vector>

#include <Eigen/Dense>
#include <Eigen/Geometry>

#include "kalman_ou_iii/SeaStateFusionFilter_OU_III.h"

namespace {
using Filter = SeaStateFusionFilter_OU_III<TrackerType::KALMANF>;
constexpr float DT = 0.005f;
constexpr float G = 9.80665f;

bool finite_positive(float x) { return std::isfinite(x) && x > 0.0f; }
}

int main(int argc, char** argv) {
    if (argc != 2) {
        std::cerr << "usage: ou3-sea3-same-driver-startup-test <vertical-accel.txt>\n";
        return 2;
    }

    std::ifstream in(argv[1]);
    if (!in) {
        std::cerr << "cannot open source prehistory\n";
        return 2;
    }
    std::vector<float> a_up;
    double x = 0.0;
    while (in >> x) {
        if (!std::isfinite(x)) {
            std::cerr << "nonfinite source sample\n";
            return 2;
        }
        a_up.push_back(static_cast<float>(x));
    }
    if (a_up.empty()) {
        std::cerr << "empty source prehistory\n";
        return 2;
    }

    Filter f(/*with_mag=*/true);
    // The declared theorem domain records the outer wrapper's 10 s startup
    // setting; set the same public shipping knob rather than modifying code.
    f.setOnlineTuneWarmupSec(10.0f);
    f.initialize(Eigen::Vector3f::Constant(0.0148f),
                 Eigen::Vector3f::Constant(0.00157f),
                 Eigen::Vector3f::Constant(0.3f));

    const Eigen::Vector3f gyro = Eigen::Vector3f::Zero();
    auto acc_from_up = [](float up) {
        // VerticalAccelComplementary reports up=-(acc_z+g) at identity.
        // Therefore acc_z=-g-up is the exact inverse measurement mapping for
        // the fixed zero-rotation/identity-attitude source member.
        return Eigen::Vector3f(0.0f, 0.0f, -G - up);
    };

    f.initialize_from_acc(acc_from_up(a_up.front()));

    int first_ready = -1;
    float tau_ready = NAN;
    float sigma_ready = NAN;
    float rs_ready = NAN;
    float period_ready = NAN;
    float guard_engagement_max = 0.0f;
    for (std::size_t k = 0; k < a_up.size(); ++k) {
        f.updateFrontEnd(DT, gyro, acc_from_up(a_up[k]));
        guard_engagement_max = std::max(guard_engagement_max,
                                        f.accelVibrationGuardEngagement());
        if (first_ready < 0 && f.isTunerReady()) {
            first_ready = static_cast<int>(k);
            tau_ready = f.getTauApplied();
            sigma_ready = f.getSigmaApplied();
            rs_ready = f.getRSApplied();
            period_ready = f.getWavePeriodSec();
        }
    }

    const bool ready = f.isTunerReady();
    const bool usable = f.wavePeriodUsable();
    const bool proxy = f.startupProxyInitialized();
    const bool schedule_ok = finite_positive(tau_ready) && finite_positive(sigma_ready)
                          && finite_positive(rs_ready) && finite_positive(period_ready);
    const bool guard_dormant = guard_engagement_max == 0.0f;

    std::cout << std::setprecision(10)
              << "{\n"
              << "  \"same_driver_samples\": " << a_up.size() << ",\n"
              << "  \"first_tuner_ready_sample\": " << first_ready << ",\n"
              << "  \"first_tuner_ready_time_s\": "
              << (first_ready >= 0 ? (first_ready + 1) * DT : -1.0f) << ",\n"
              << "  \"wave_period_usable\": " << (usable ? "true" : "false") << ",\n"
              << "  \"startup_proxy_initialized\": " << (proxy ? "true" : "false") << ",\n"
              << "  \"tuner_ready\": " << (ready ? "true" : "false") << ",\n"
              << "  \"tau_applied_at_ready_s\": " << tau_ready << ",\n"
              << "  \"sigma_applied_at_ready_mps2\": " << sigma_ready << ",\n"
              << "  \"RS_applied_at_ready_m_s\": " << rs_ready << ",\n"
              << "  \"wave_period_at_ready_s\": " << period_ready << ",\n"
              << "  \"max_vibration_guard_engagement\": " << guard_engagement_max << ",\n"
              << "  \"shipping_schedule_positive_finite\": "
              << (schedule_ok ? "true" : "false") << ",\n"
              << "  \"vibration_guard_dormant_transparent\": "
              << (guard_dormant ? "true" : "false") << "\n"
              << "}\n";

    if (!ready) {
        std::cerr << "same-driver prehistory did not reach shipping TunerReady\n";
        return 1;
    }
    if (!usable || !proxy || !schedule_ok) {
        std::cerr << "TunerReady lacks required WPE/proxy/schedule state\n";
        return 1;
    }
    if (!guard_dormant) {
        std::cerr << "same-driver point leaves theorem's dormant vibration-guard branch\n";
        return 1;
    }
    return 0;
}
